440	// startTask/cancelCurrentTask) and its wiring into b.on('health', ...) in
441	// wireBot(). PANIC_CAMP_POS must stay in sync with skills.js's own (private)
442	// CAMP_POS constant, same duplication tradeoff as IDLE_GUARD_DEPOT_POS below.
443	const PANIC_HEALTH_THRESHOLD = 8; // matches skills.js's checkHealthRetreat threshold
444	const PANIC_COOLDOWN_MS = 30000; // don't refire the reflex on every single low-health tick
445	const PANIC_CAMP_POS = { x: 12, y: 89, z: 56 }; // must stay in sync with skills.js's CAMP_POS
446	const PANIC_FAR_RADIUS = 40; // blocks from camp — past this, a blind flee is riskier than sealing in place
447	const PANIC_DEEP_DELTA = 15; // blocks below camp's Y — this deep, seal+eat beats fleeing back to the surface
448	let lastPanicAt = 0;
449	
450	const EVENTS_MAX = 500;
451	const eventsBuf = [];
452	let eventSeq = 0;
453	
454	// RING FILTER (FEEDBACK "event ring flooded by FEL join/leave spam — useless
455	// for forensics", team-lead 2026-09-01) — Ook's ring at seq 10k+ was almost
456	// entirely "[FEL] X joined/left the game" from their reconnect storms, and a
457	// task-replacement sequence could not be reconstructed because the real
458	// events had already been shifted out of a 500-entry buffer. Join/leave of
459	// OUR OWN bots stays (that IS forensics — a crew bot relogging mid-task is
460	// exactly what you need to see); everyone else's is dropped at the two
461	// handler sites below, deliberately NOT inside pushEvent, so every other
462	// caller keeps writing to the ring unconditionally and nothing else can be
463	// silently swallowed by a filter it never asked for.
464	const OUR_BOTS = /^(Grog|UngaBunga|Zug|Bonk|Thak|Ook|Durk|Mog|TestRock|BariBrute)$/;
465	const JOIN_LEAVE_RE = /(?:^|\s)(\S+) (?:joined|left) the game$/;
466	
467	function isForeignJoinLeave(text) {
468	  const m = JOIN_LEAVE_RE.exec(String(text).trim());
469	  if (!m) return false;
470	  // Names arrive tagged in this world ("[FEL] Friedrich", "[CAVE] Grog") —
471	  // strip any bracketed tribe prefix before matching the roster.
472	  const who = m[1].replace(/^\[[^\]]*\]/, '');
473	  return !OUR_BOTS.test(who);
474	}
475	
476	function pushEvent(type, msg) {
477	  eventSeq++;
478	  eventsBuf.push({ seq: eventSeq, ts: new Date().toISOString(), type, msg: String(msg) });
479	  if (eventsBuf.length > EVENTS_MAX) eventsBuf.shift();
480	}
481	
482	// TASK SOURCE (FEEDBACK "UPDATE on force task silently replaced: may be
483	// TWO-COMMANDERS problem", team-lead 2026-09-01) — a forced goto on Ook was
484	// replaced within 45s by a hunt task while OokDriver was independently
485	// running his own meat-run chain. Nobody could prove afterwards WHO issued
486	// the replacement: orchestrator, driver, and idle-guard all looked identical
