function summarizeInventory(b) {
  const map = new Map();
  for (const it of b.inventory.items()) {
    map.set(it.name, (map.get(it.name) || 0) + it.count);
  }
  return Array.from(map, ([itemName, count]) => ({ name: itemName, count }));
}

